// ============================================================================
// DSI_apb: APB4 register wrapper around DSI_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/DSI.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/DSI.md
// ============================================================================
module DSI_apb #(
  parameter int BTA_TO = 512
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tx_bit,
  output logic tx_valid,
  output logic tx_oe,
  input logic rx_bit
);
  localparam logic [31:0] ID_VALUE = 32'h44530200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [41:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd42) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[8] | hit[9] | hit[10] | hit[11] | hit[12] | hit[13] | hit[14] | hit[15] | hit[16] | hit[17] | hit[18] | hit[19] | hit[20] | hit[21] | hit[22] | hit[23] | hit[24] | hit[25] | hit[26] | hit[27] | hit[28] | hit[29] | hit[30] | hit[31] | hit[32] | hit[33] | hit[34] | hit[35] | hit[36] | hit[37] | hit[38] | hit[39])));   // core registers take whole words

  // ---------------- core ----------------
  logic          c_irq;
  logic          c_tx_oe;
  logic          c_cmd_valid;
  logic [2:0]    c_cmd_op;
  logic [5:0]    c_cmd_dt;
  logic [7:0]    c_cmd_dcs;
  logic [15:0]   c_cmd_len;
  logic [15:0]   c_cmd_len2;
  logic          c_cmd_busy;
  logic          c_pl_we;
  logic [7:0]    c_pl_wdata;
  logic          c_bta_done;
  logic [23:0]   c_bta_data;
  logic [15:0]   c_pkt_cnt;
  DSI_top #(.BTA_TO(BTA_TO)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .irq(c_irq),
    .tx_bit(tx_bit),
    .tx_valid(tx_valid),
    .tx_oe(c_tx_oe),
    .rx_bit(rx_bit),
    .cmd_valid(c_cmd_valid),
    .cmd_op(c_cmd_op),
    .cmd_dt(c_cmd_dt),
    .cmd_dcs(c_cmd_dcs),
    .cmd_len(c_cmd_len),
    .cmd_len2(c_cmd_len2),
    .cmd_busy(c_cmd_busy),
    .pl_we(c_pl_we),
    .pl_addr((wr ? ((hit[8] ? 5'd0 : 5'd0) | (hit[9] ? 5'd1 : 5'd0) | (hit[10] ? 5'd2 : 5'd0) | (hit[11] ? 5'd3 : 5'd0) | (hit[12] ? 5'd4 : 5'd0) | (hit[13] ? 5'd5 : 5'd0) | (hit[14] ? 5'd6 : 5'd0) | (hit[15] ? 5'd7 : 5'd0) | (hit[16] ? 5'd8 : 5'd0) | (hit[17] ? 5'd9 : 5'd0) | (hit[18] ? 5'd10 : 5'd0) | (hit[19] ? 5'd11 : 5'd0) | (hit[20] ? 5'd12 : 5'd0) | (hit[21] ? 5'd13 : 5'd0) | (hit[22] ? 5'd14 : 5'd0) | (hit[23] ? 5'd15 : 5'd0) | (hit[24] ? 5'd16 : 5'd0) | (hit[25] ? 5'd17 : 5'd0) | (hit[26] ? 5'd18 : 5'd0) | (hit[27] ? 5'd19 : 5'd0) | (hit[28] ? 5'd20 : 5'd0) | (hit[29] ? 5'd21 : 5'd0) | (hit[30] ? 5'd22 : 5'd0) | (hit[31] ? 5'd23 : 5'd0) | (hit[32] ? 5'd24 : 5'd0) | (hit[33] ? 5'd25 : 5'd0) | (hit[34] ? 5'd26 : 5'd0) | (hit[35] ? 5'd27 : 5'd0) | (hit[36] ? 5'd28 : 5'd0) | (hit[37] ? 5'd29 : 5'd0) | (hit[38] ? 5'd30 : 5'd0) | (hit[39] ? 5'd31 : 5'd0)) : 5'd0)),
    .pl_wdata(c_pl_wdata),
    .bta_done(c_bta_done),
    .bta_data(c_bta_data),
    .pkt_cnt(c_pkt_cnt)
  );
  assign tx_oe = c_tx_oe;  // also readable in the registers

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [16:0] r_CMD;   // 12'h014 CMD
  logic [31:0] r_LEN;   // 12'h018 LEN
  logic [0:0] p_GO;   // 12'h01C GO (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CMD <= 17'h0;
      r_LEN <= 32'h0;
      p_GO <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CMD <= (r_CMD & ~wmask[16:0]) | (PWDATA[16:0] & wmask[16:0]);
      if (wr && hit[6]) r_LEN <= (r_LEN & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_GO <= (wr && hit[7]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cmd_op = r_CMD[2:0];
  assign c_cmd_dt = r_CMD[8:3];
  assign c_cmd_dcs = r_CMD[16:9];
  assign c_cmd_len = r_LEN[15:0];
  assign c_cmd_len2 = r_LEN[31:16];
  assign c_cmd_valid = p_GO;
  // PAYLOAD: the core's register port (indices on the instance)
  assign c_pl_we = wr & (PSTRB == 4'hF) & (hit[8] | hit[9] | hit[10] | hit[11] | hit[12] | hit[13] | hit[14] | hit[15] | hit[16] | hit[17] | hit[18] | hit[19] | hit[20] | hit[21] | hit[22] | hit[23] | hit[24] | hit[25] | hit[26] | hit[27] | hit[28] | hit[29] | hit[30] | hit[31] | hit[32] | hit[33] | hit[34] | hit[35] | hit[36] | hit[37] | hit[38] | hit[39]);
  assign c_pl_wdata = PWDATA[7:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_bta_done;
    irq_set[1] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CMD);
      10'd6: apb_rdata = 32'(r_LEN);
      10'd40: apb_rdata = 32'({c_pkt_cnt, c_tx_oe, c_cmd_busy});
      10'd41: apb_rdata = 32'({c_bta_data});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
